function reprice(v){const q=state().query,n=Number(v);if(!q||!Number.isFinite(n)||n<.5||n>200)return toast('距离须为0.5至200公里');q.distance=n;q.distanceSource='手动模拟距离';q.ts=Date.now();state().distance=n;save();paint();}
function open(){NorthTravelHome.home();active=true;view='cover';origin=null;paint();}
function deactivate(){active=false;locationToken++;locating=false;}
function cover(){active=true;view='cover';origin=null;paint();}
