// Simulated routes may be chosen by the role; only this account/chat supplies context.
function chatContext(c){if(!c||c.deleted||c.blocked||c.isPhoneFriend||account()!=='main'||typeof msgs!=='function')return [];const now=Date.now(),list=msgs(c.id).filter(m=>m.role==='user'&&m.type==='text'&&Number.isFinite(m.time)&&now-m.time>=-5000&&now-m.time<=600000).slice(-8);if(/(?:不要|不用|别|取消).{0,8}(?:叫|打|订)?车/.test(String(list.at(-1)&&list.at(-1).content||'')))return [];return list;}
function sharedQuery(c){const q=state().query;return q&&c&&q.accountId===account()&&Date.now()-q.ts<=600000&&!validate(q)&&(q.roleIds.includes(c.id)||q.helperId===c.id)?q:null;}
function rolePrompt(c){const mine=rows().filter(o=>o.knownRoleIds.includes(c.id)),q=sharedQuery(c),chat=chatContext(c);
 return '\n\n# 小手机模拟打车\n'+(mine.length?mine.map(summary).join('\n'):'暂无你知情的打车订单。')+'\n这是小手机模拟叫车，你可以按人物意愿直接为用户或自己安排车辆。输出 [叫车|上车地点|目的地|快车/出租车/专车/豪华车|给你/我们一起/我自己]。用户已说的地点优先使用；没说具体地点时可以自行填写模拟上车点，自己选或编酒吧等目的地名称，不必要求用户先打开打车页面或提供准确地址。未知真实GPS不能伪装成已获取定位。已有共享查询也可输出 [叫车|目的地|车型|乘车人] 或 [叫车查询]。仅用你自己的钱包／银行余额，不用用户钱包或亲属卡；订单、地址选择和司机均为模拟，实际订单创建后才说叫好了。'+(q?'\n用户共享的打车查询：'+JSON.stringify(q):'')+(chat.length?'\n本聊天用户提供的叫车信息：'+chat.map(m=>m.content).join('\n'):'');}
function chatQuery(c,pickup,destination,guest){const list=chatContext(c),text=list.map(m=>m.content).join('\n');if(!list.length||!pickup||!destination||!['给你','我们一起','我自己'].includes(guest))return null;const last=list.at(-1),prior=raw().find(o=>owned(o)&&o.cid===c.id&&o.chatRequestTime>=last.time);if(prior)return null;return {chatRequestTime:last.time,accountId:account(),from:pickup,to:destination,coords:null,locationAt:0,mode:guest==='给你'?'solo':guest==='我自己'?'give':'together',roleIds:guest==='给你'?[]:[c.id],helperId:c.id,distance:8,distanceSource:'角色选择模拟地点／默认模拟距离，非真实道路路线',ts:last.time};}
let roleError='';
function roleQuery(c,destination,type,guest,pickup){roleError='';const q=pickup?chatQuery(c,pickup,destination,guest):sharedQuery(c);if(!q){roleError='没有可用的当前聊天或共享查询，请重新发起叫车';return false;}const copy={...q,roleIds:[...q.roleIds],people:q.people&&q.people.map(p=>({...p}))};if(destination&&destination.trim()!==q.to)return false;if(guest==='给你'){if(q.mode==='give')return false;copy.mode='solo';copy.roleIds=[];}else if(guest==='我们一起'){if(q.mode==='give')return false;copy.mode='together';copy.roleIds=[c.id];}else if(guest==='我自己'){if(q.mode!=='give'||q.roleIds[0]!==c.id)return false;}else if(guest)return false;const error=validate(copy),fare=quotes(copy).find(x=>x.id===(type||'express')),funds=tvHotelRoleMoney(c);if(error){roleError=error;return false;}if(!fare){roleError='车型无效';return false;}if(!funds||NorthHotelData.moneyNext(funds.balance,-fare.cents)===null){roleError='角色可用余额不足或无效';return false;}return book(copy,type||'express',c);}
function fallbackRoute(content,c,list){const text=list.map(m=>String(m.content||'')).join('\n'),last=String(list.at(-1).content||'').trim(),pickupMatch=text.match(/(?:我在|上车地点[：:]?|从)([^，。！？\n]{1,40})/),pickup=pickupMatch?pickupMatch[1].trim():last.length<=30&&!/[叫打订帮车？?]/.test(last)?last:'约定上车点（模拟）',type=/豪华/.test(content+' '+text)?'豪华车':/专车/.test(content+' '+text)?'专车':/出租/.test(content+' '+text)?'出租车':'快车',destination=/酒吧/.test(content+' '+text)?'月光酒吧（模拟）':'目的地（模拟）';return '[叫车|'+pickup.replace(/[<>[]|\r\n]/g,'').slice(0,150)+'|'+destination+'|'+type+'|给你]';}
async function prepare(content,c,repair){const text=String(content||'');if(!/\[叫车(?:查询\]|\|[^\]\n]+\])/.test(text)||sharedQuery(c)||/\[叫车\|[^|\]\n]+\|[^|\]\n]+\|[^|\]\n]+\|[^|\]\n]+\]/.test(text))return text;const aid=account(),list=chatContext(c);if(!list.length)return text;const context=list.map(m=>m.content).join('\n');let fixed='';if(typeof repair==='function')try{fixed=String(await repair('上一条模拟叫车操作尚未创建订单、尚未扣款。请只补全这一轮叫车：当前本角色本账号用户聊天：\n'+context+'\n保留你的口吻，单独输出 [叫车|上车地点|目的地|快车/出租车/专车/豪华车|给你/我们一起/我自己]。这是模拟出行，用户提供的地点优先使用；未给准确地点时你可以自行填写模拟上车点、自己选择或编一个酒吧等目的地名称，不要追问具体地址，不需要页面查询。车型按本轮要求。不能假装取得GPS，不能借其他角色信息或代写用户消息。不要再输出 [叫车查询]。')||'');}catch(_){}if(account()!==aid||chatContext(c).map(m=>m.content).join('\n')!==context)return '';if(/\[叫车\|[^|\]\n]+\|[^|\]\n]+\|[^|\]\n]+\|[^|\]\n]+\]/.test(fixed))return fixed;return text.replace(/\[叫车(?:查询\]|\|[^\]\n]+\])/g,'')+'\n'+fallbackRoute(text,c,list);}
function consume(content,c,done){let failed=false;const finish=ok=>{failed=failed||!ok;if(typeof done==='function')done(!!ok);};const out=String(content||'').replace(/\[打车提醒\|[^\]\n]+\]/g,'').replace(/\[叫车\|([^\]\n]+)\]/g,(_,args)=>{const a=args.split('|').map(x=>x.trim()),full=a.length===4,type={快车:'express',滴滴快车:'express',出租车:'taxi',专车:'special',豪华车:'luxury',滴滴豪华车:'luxury'}[a[full?2:1]],ok=(full||a.length===3)&&type&&roleQuery(c,a[full?1:0],type,a[full?3:2],full?a[0]:null);finish(ok);return '';}).replace(/\[叫车查询\]/g,()=>{finish(roleQuery(c));return '';});if(failed&&c&&typeof msgs==='function'){const reason=roleError||'路线、乘车人或报价已变化，请重新确认';msgs(c.id).push({id:uid(),time:Date.now(),role:'user',type:'sys',content:'未叫车：'+reason+'。未创建新订单，未扣款。'});save();}return failed?'':out;}
function inspection(since=0){return rows().filter(o=>o.ts>since).slice(-12).map(o=>(NorthHotelData.roleOrder(o)?'·角色为她预订的打车订单：':'·她自己预订的打车订单：')+summary(o)).join('\n')+'\n';}
